import requests

BASE_URL = "http://localhost:3001"
LOGIN_ENDPOINT = "/api/auth/login"
TIMEOUT = 30

def test_post_api_auth_login_with_valid_and_invalid_credentials():
    url = BASE_URL + LOGIN_ENDPOINT

    # Valid credentials test
    valid_payload = {
        "email": "demo@harshita.ai",
        "password": "demo123"
    }
    try:
        valid_response = requests.post(url, json=valid_payload, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed with exception: {e}"
    assert valid_response.status_code == 200, f"Expected 200 for valid login but got {valid_response.status_code}"
    valid_json = valid_response.json()
    assert "success" in valid_json and valid_json["success"] is True, "Login success flag missing or false in valid login"
    assert "token" in valid_json and isinstance(valid_json["token"], str) and len(valid_json["token"]) > 0, "JWT token missing or invalid in valid login"

    # Invalid credentials test (wrong password)
    invalid_payload = {
        "email": "demo@harshita.ai",
        "password": "wrongpassword"
    }
    try:
        invalid_response = requests.post(url, json=invalid_payload, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed with exception: {e}"
    assert invalid_response.status_code == 401, f"Expected 401 for invalid login but got {invalid_response.status_code}"

    # Invalid credentials test (wrong email)
    invalid_email_payload = {
        "email": "wrong@harshita.ai",
        "password": "demo123"
    }
    try:
        invalid_email_response = requests.post(url, json=invalid_email_payload, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed with exception: {e}"
    assert invalid_email_response.status_code == 401, f"Expected 401 for invalid login with wrong email but got {invalid_email_response.status_code}"

test_post_api_auth_login_with_valid_and_invalid_credentials()

import requests

BASE_URL = "http://localhost:3001"
TIMEOUT = 30

def test_get_api_dashboard_stats_returns_correct_statistics():
    url = f"{BASE_URL}/api/dashboard/stats"
    try:
        response = requests.get(url, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request to {url} failed with exception: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"
    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert isinstance(data, dict), "Response JSON is not an object"

    # Validate required fields presence and types
    required_fields = {
        "totalTransactions": int,
        "activeOperators": int,
        "centerRevenue": (int, float)
    }

    for field, expected_type in required_fields.items():
        assert field in data, f"Field '{field}' missing in response"
        assert isinstance(data[field], expected_type), f"Field '{field}' is not of type {expected_type}"

test_get_api_dashboard_stats_returns_correct_statistics()

import requests

BASE_URL = "http://localhost:3001"
TIMEOUT = 30

def test_post_api_pdf_process_ta_valid_and_missing_pdfpath():
    url = f"{BASE_URL}/api/pdf/process-ta"
    headers = {
        "Content-Type": "application/json"
    }

    # Test with valid pdfPath
    valid_payload = {
        "pdfPath": "sample.pdf"
    }
    try:
        response_valid = requests.post(url, json=valid_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed for valid pdfPath: {e}"
    else:
        assert response_valid.status_code == 200, f"Expected 200, got {response_valid.status_code}"
        try:
            json_resp = response_valid.json()
        except ValueError:
            assert False, "Response is not valid JSON for valid pdfPath"
        assert isinstance(json_resp, dict), "Response JSON should be an object on success"

    # Test with missing pdfPath
    missing_payload = {}
    try:
        response_missing = requests.post(url, json=missing_payload, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed for missing pdfPath: {e}"
    else:
        assert response_missing.status_code == 400, f"Expected 400, got {response_missing.status_code}"

test_post_api_pdf_process_ta_valid_and_missing_pdfpath()
